#include <iostream>
using namespace std;
int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++) {
        if (arr[j] > pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return (i + 1);
}
void quickSelect(int arr[], int l, int r, int k) {
    if (k > 0 && k <= r - l + 1) {
        int idx = partition(arr, l, r);
        if (idx == k - 1)
            return;
        else if (idx > k - 1)
            quickSelect(arr, l, idx - 1, k);
        else
            quickSelect(arr, idx + 1, r, k);
    }
}
int findSecondLargest(int arr[], int n) {
    quickSelect(arr, 0, n - 1, n - 2);
    return arr[n - 2];
}
