One common algorithm for finding the second largest element in an unsorted array is called "Selection Sort". This algorithm works by repeatedly selecting the maximum (or minimum) element from the remaining elements and swapping it with the first element until the entire array is sorted.
Here's how you could implement this algorithm in C++:
```
#include <iostream>
using namespace std;
int findSecondLargest(int arr[], int n) {
    // Initialize variables to store the maximum and second largest elements
    int max1 = INT_MIN, max2 = INT_MIN;

    // Traverse through each element in the array
    for (int i = 0; i < n; i++) {
        // If current element is greater than max1, update max1 and max2
        if (arr[i] > max1) {
            max2 = max1;
            max1 = arr[i];
        }
        // If current element is between max1 and max2, update max2
        else if (arr[i] > max2 && arr[i] != max1) {
            max2 = arr[i];
        }
